import os
import logging
import time
from datetime import datetime
from taf.sbts.oam.coam.admin.exceptions import DataNotAvailable
from taf.rfrl.bts.devices.generic_bts import GenericBts, login_logout


class MeasureSoftwareDownload(GenericBts):
    """Base keywords for eNB and gNB"""

    def __init__(self, bts_type='GNB'):
        """
        Constructor of GenericBbbu class.
        :param bts_type: GNB|ENB
        :return: None
        """
        super(MeasureSoftwareDownload, self).__init__(bts_type=bts_type)

    @login_logout
    def measure_software_download_to_du_time(self, path, success_rate, average_target, timeout, bts_id=0, du_id=0):
        """
        Perform DU update, measure time and verify if meet average time target and success rate ratio.
        :param path: list of absolute paths on VM with expected DU build to update
        :param bts_id:  default BTS id
        :param du_id: default DU id
        :param success_rate: Target PASSED to RUNS ratio
        :param average_target: Target sw download time in seconds.
        :param timeout:  time in seconds to wait for sw download
        """
        maximum_target = 1.2 * float(average_target)
        runs = len(path)
        download_state = None
        passed = 0
        failed = 0
        passed_run_times = []
        for p in path:
            if not os.path.exists(p):
                logging.warning("FileNotFoundError: {}".format(p))
                runs -= 1
                continue
            try:
                start_update_time = time.time()
                logging.info("Start SW download: {}".format(datetime.now()))
                download_state = self.admin.update_software(sw_package=p, should_activate=False,
                                                            timeout=int(timeout),
                                                            connection=self.rest_alias.format(bts_id, du_id))
                end_update_time = time.time()
                time.sleep(60)

                if download_state == 'Software update has been completed':
                    sw_download_duration = end_update_time - start_update_time
                    logging.info("SW Download duration of {}: {}".format(p, round(sw_download_duration, 2)))
                    if sw_download_duration < 300:
                        runs -= 1
                        logging.warning("Duration too short - build was already downloaded")
                    elif sw_download_duration <= maximum_target:
                        passed_run_times.append(round(sw_download_duration, 2))
                        passed += 1
                    else:
                        failed += 1
                else:
                    logging.warning("SW Download of {} with state {}".format(p, download_state))
                    failed += 1
            except DataNotAvailable:
                logging.warning("DataNotAvailable: SW download state of {} is {}".format(p, download_state))
                failed += 1

        exceptions = []
        if len(passed_run_times) > 0:
            average_sw_download_time = sum(passed_run_times) / len(passed_run_times)
            logging.info("Average SW download duration {}".format(average_sw_download_time))

            if int(average_target) <= int(average_sw_download_time):
                exceptions.append(AverageSwDownloadDurationNotMet("Average download time {}s exceed "
                                                                  "presume value {}s".format(average_sw_download_time,
                                                                                             average_target)))

            passed_ratio = passed / runs
            if float(passed_ratio) < float(success_rate):
                exceptions.append(SwDownloadDurationNotMet("Runs: {}, Failed: {}, Ratio: {} "
                                                           "Target not met".format(runs, failed, passed_ratio)))

        if exceptions:
            raise SwDownloadDurationNotMet("\n".join([repr(e) for e in exceptions]))
        elif runs == 0:
            raise SwDownloadDurationNotMet("No software download was performed.")
        else:
            logging.info("Runs: {}, Ratio: {}, Avg time: {} "
                         "Max time: {}".format(runs, passed_ratio, round(average_sw_download_time, 2),
                                               max(passed_run_times)))


class SwDownloadDurationNotMet(Exception):
    pass


class AverageSwDownloadDurationNotMet(SwDownloadDurationNotMet):
    pass
